ON CONFLICT(imdb_id) DO UPDATE SET
  title = excluded.title,
  release_year = excluded.release_year,
  genre = excluded.genre,
  poster_key = excluded.poster_key,
  source_url = CASE WHEN excluded.source_url <> '' THEN excluded.source_url ELSE pix_movie_stats.source_url END,
  poster_source_url = excluded.poster_source_url,
  synopsis = CASE WHEN pix_movie_stats.synopsis = '' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,
  synopsis_source_url = CASE WHEN pix_movie_stats.synopsis_source_url = '' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,
  attributes_json = CASE WHEN pix_movie_stats.attributes_json = '' OR pix_movie_stats.attributes_json = '{{}}' THEN excluded.attributes_json ELSE pix_movie_stats.attributes_json END,
  updated_at = excluded.updated_at;
